import heapq

def match(orders):
    buy_heap = []  # (-price, seq, id) max-heap by price, then time
    sell_heap = []  # (price, seq, id) min-heap by price, then time
    order_qty = {}  # id -> remaining qty
    order_side = {}
    order_price = {}
    active = set()  # ids that are active (resting in book)
    seq_counter = 0
    trades = []

    def add_to_book(side, id_, price, qty, seq):
        order_qty[id_] = qty
        order_side[id_] = side
        order_price[id_] = price
        active.add(id_)
        if side == 'buy':
            heapq.heappush(buy_heap, (-price, seq, id_))
        else:
            heapq.heappush(sell_heap, (price, seq, id_))

    for order in orders:
        typ = order[0]
        if typ == 'cancel':
            id_ = order[1]
            if id_ in active:
                active.discard(id_)
                order_qty[id_] = 0
            continue

        seq_counter += 1
        seq = seq_counter

        if typ == 'market':
            _, id_, side, qty = order
            price = None
        else:
            _, id_, side, price, qty = order

        remaining = qty

        if side == 'buy':
            opp_heap = sell_heap
        else:
            opp_heap = buy_heap

        while remaining > 0 and opp_heap:
            top = opp_heap[0]
            opp_id = top[2]
            if opp_id not in active or order_qty.get(opp_id, 0) <= 0:
                heapq.heappop(opp_heap)
                continue
            opp_price = order_price[opp_id]
            if typ != 'market' and price is not None:
                if side == 'buy' and opp_price > price:
                    break
                if side == 'sell' and opp_price < price:
                    break
            # match
            heapq.heappop(opp_heap)
            trade_qty = min(remaining, order_qty[opp_id])
            if side == 'buy':
                trades.append([id_, opp_id, opp_price, trade_qty])
            else:
                trades.append([opp_id, id_, opp_price, trade_qty])
            remaining -= trade_qty
            order_qty[opp_id] -= trade_qty
            if order_qty[opp_id] > 0:
                heapq.heappush(opp_heap, top)  # push back, same seq preserves time priority
            else:
                active.discard(opp_id)

        if typ == 'limit':
            if remaining > 0:
                add_to_book(side, id_, price, remaining, seq)
            else:
                order_qty[id_] = 0
        else:
            # ioc or market: discard remainder
            order_qty[id_] = 0

    return trades

